import { readFile } from 'node:fs/promises'

import './wasm_exec.js'

// Captured now: another copy of this package, maybe built by a different Go
// version, replaces globalThis.Go when it is imported.
const { Go } = globalThis

let bridgePromise

const loadBridge = () => {
  bridgePromise ??= (async () => {
    const go = new Go()
    const wasm = await readFile(new URL('./matcher.wasm', import.meta.url))
    const { instance } = await WebAssembly.instantiate(wasm, go.importObject)
    // go.run only settles when the Go program exits, which it never does;
    // main registers the bridge before blocking, so it is ready on return.
    go.run(instance)
    return globalThis.__netlifyRedirectMatcher
  })().catch((error) => {
    bridgePromise = undefined
    throw error
  })
  return bridgePromise
}

const unwrap = (reply) => {
  if (reply.error !== undefined) {
    throw new Error(reply.error)
  }
  return reply.ok
}

const stringRecord = (record, name, normalizeKey) => {
  if (record === undefined) {
    return {}
  }
  let entries
  if (record !== null && typeof record === 'object') {
    if (typeof record[Symbol.iterator] === 'function') {
      entries = record
    } else {
      // Dictionaries built on a constructor-less prototype, like the ones
      // `cookie` returns, count as plain; class instances such as URL do not.
      const constructor = Object.getPrototypeOf(record)?.constructor
      if (constructor === undefined || constructor === Object) {
        entries = Object.entries(record)
      }
    }
  }
  if (entries === undefined) {
    throw new TypeError(`${name} must be a plain object, Headers, Map or iterable of [name, value] pairs`)
  }
  const out = {}
  for (const [key, raw] of entries) {
    // Multi-value headers (as from toMultiValueHeaders) match on their first
    // value.
    const value = Array.isArray(raw) ? raw[0] : raw
    if (value !== undefined && value !== null) {
      out[normalizeKey(key)] = String(value)
    }
  }
  return out
}

const toBridgeRequest = (req) => {
  if (req === null || typeof req !== 'object') {
    throw new TypeError('request must be an object')
  }
  return {
    scheme: String(req.scheme ?? ''),
    host: String(req.host ?? ''),
    path: String(req.path ?? ''),
    query: String(req.query ?? ''),
    headers: stringRecord(req.headers, 'request.headers', (key) => key.toLowerCase()),
    cookies: stringRecord(req.cookies, 'request.cookies', (key) => key),
  }
}

// A throw from a finalization callback is an uncaught exception in the host
// process, and nobody is left to handle a failed free.
const finalizer = new FinalizationRegistry(({ bridge, id }) => {
  try {
    bridge.free(id)
  } catch {
    // The matcher is unreachable either way.
  }
})

class Matcher {
  #bridge
  #id
  #parseErrors
  #rulesCount
  #closed = false

  constructor(bridge, created) {
    this.#bridge = bridge
    this.#id = created.id
    this.#parseErrors = Object.freeze(created.parseErrors.map((error) => Object.freeze(error)))
    this.#rulesCount = created.rulesCount
    finalizer.register(this, { bridge, id: created.id }, this)
  }

  get parseErrors() {
    return this.#parseErrors
  }

  get rulesCount() {
    return this.#rulesCount
  }

  match(req) {
    if (this.#closed) {
      throw new Error('matcher is closed')
    }
    return unwrap(this.#bridge.match(this.#id, toBridgeRequest(req))) ?? null
  }

  close() {
    if (this.#closed) {
      return
    }
    this.#closed = true
    finalizer.unregister(this)
    unwrap(this.#bridge.free(this.#id))
  }
}

export const createMatcher = async (rules, options = {}) => {
  let rulesJSON
  if (typeof rules === 'string') {
    rulesJSON = rules
  } else if (Array.isArray(rules)) {
    rulesJSON = JSON.stringify(rules)
  } else {
    throw new TypeError('rules must be a JSON string or an array')
  }
  if (options === null || typeof options !== 'object') {
    throw new TypeError('options must be an object')
  }

  const bridge = await loadBridge()
  const created = unwrap(
    bridge.create(rulesJSON, {
      jwtSecret: String(options.jwtSecret ?? ''),
      jwtRoleClaim: String(options.jwtRoleClaim ?? ''),
      allowMidSegmentCaptures: Boolean(options.allowMidSegmentCaptures),
    }),
  )
  return new Matcher(bridge, created)
}
